import {
  Area,
  AreaChart,
  CartesianGrid,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/custom/blocks/CardBlock";
import { Badge } from "@/components/custom/ui/badge";
import { accentStyle } from "@/lib/accent";
import { useChartTokens } from "@/lib/chart-tokens";

const revenue = [
  { month: "Jan", mrr: 12400, expansion: 2100 },
  { month: "Feb", mrr: 14850, expansion: 2600 },
  { month: "Mar", mrr: 15900, expansion: 2400 },
  { month: "Apr", mrr: 18600, expansion: 3100 },
  { month: "May", mrr: 21050, expansion: 3800 },
  { month: "Jun", mrr: 24900, expansion: 4200 },
  { month: "Jul", mrr: 26400, expansion: 4050 },
  { month: "Aug", mrr: 29800, expansion: 5300 },
];

const currency = (value: number) => `$${(value / 1000).toFixed(1)}k`;

/**
 * Recharts draws the plot; the surrounding chrome — card, title, legend,
 * tooltip — is all Avara UI. That split is the whole integration: the
 * chart library never renders anything the design system already owns.
 */
export default function RechartsRevenue({ color }: { color?: string } = {}) {
  const tokens = useChartTokens(color);

  return (
    <Card className="w-full max-w-3xl min-w-0 overflow-hidden" style={accentStyle(color)}>
      <CardHeader className="p-4 sm:p-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 sm:gap-4">
          <div>
            <CardTitle className="text-base sm:text-lg">Recurring revenue</CardTitle>
            <CardDescription className="text-xs sm:text-sm">Monthly recurring revenue and expansion</CardDescription>
          </div>
          <Badge variant="outline" className="w-fit border-primary/25 bg-primary/10 text-primary font-medium text-xs">
            +18.4%
          </Badge>
        </div>
      </CardHeader>

      <CardContent className="p-4 sm:p-6 pt-0 sm:pt-0">
        <div className="h-[220px] sm:h-[280px] w-full min-w-0">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={revenue} margin={{ top: 8, right: 6, bottom: 0, left: -14 }}>
              <defs>
                <linearGradient id="mrrFill" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor={tokens.series[0]} stopOpacity={0.35} />
                  <stop offset="100%" stopColor={tokens.series[0]} stopOpacity={0} />
                </linearGradient>
                <linearGradient id="expansionFill" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor={tokens.series[1]} stopOpacity={0.3} />
                  <stop offset="100%" stopColor={tokens.series[1]} stopOpacity={0} />
                </linearGradient>
              </defs>

              <CartesianGrid strokeDasharray="4 4" stroke={tokens.border} vertical={false} />
              <XAxis
                dataKey="month"
                tickLine={false}
                axisLine={false}
                tick={{ fill: tokens.muted, fontSize: 11 }}
                interval="preserveStartEnd"
                minTickGap={6}
              />
              <YAxis
                tickLine={false}
                axisLine={false}
                tickFormatter={currency}
                tick={{ fill: tokens.muted, fontSize: 11 }}
                width={38}
              />
              <Tooltip
                cursor={{ stroke: tokens.border }}
                contentStyle={{
                  background: tokens.card,
                  border: `1px solid ${tokens.border}`,
                  borderRadius: 12,
                  color: tokens.foreground,
                  fontSize: 11,
                  padding: "8px 12px",
                }}
                formatter={(value) => currency(Number(value))}
              />
              <Area
                type="monotone"
                dataKey="mrr"
                name="MRR"
                stroke={tokens.series[0]}
                strokeWidth={2}
                fill="url(#mrrFill)"
              />
              <Area
                type="monotone"
                dataKey="expansion"
                name="Expansion"
                stroke={tokens.series[1]}
                strokeWidth={2}
                fill="url(#expansionFill)"
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { cn } from "@/lib/utils";
import React from "react";

// ==========================================
// 1. ROOT CARD WRAPPER
// ==========================================
export interface CardProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: "default" | "bordered" | "flat";
  interactive?: boolean;
}

export function Card({
  className,
  variant = "bordered",
  interactive = false,
  children,
  ...props
}: CardProps) {
  const variants = {
    default: "bg-card shadow-sm border border-primary/10",
    bordered:
      "bg-card border border-primary/25 shadow-sm",
    flat: "bg-muted border border-primary/20",
  };

  return (
    <div
      className={cn(
        "rounded-xl text-card-foreground flex flex-col transition-all duration-200",
        variants[variant],
        interactive &&
          "hover:shadow-md hover:-translate-y-0.5 cursor-pointer hover:border-primary/50 active:scale-[0.98]",
        className,
      )}
      {...props}
    >
      {children}
    </div>
  );
}

// ==========================================
// 2. HEADER
// ==========================================
export function CardHeader({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div className={cn("flex flex-col space-y-1.5 p-6", className)} {...props}>
      {children}
    </div>
  );
}

export function CardTitle({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLHeadingElement>) {
  return (
    <h3
      className={cn(
        "font-semibold leading-none tracking-tight text-lg",
        className,
      )}
      {...props}
    >
      {children}
    </h3>
  );
}

export function CardDescription({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLParagraphElement>) {
  return (
    <p
      className={cn("text-sm text-muted-foreground", className)}
      {...props}
    >
      {children}
    </p>
  );
}

// ==========================================
// 3. CONTENT AREA
// ==========================================
export function CardContent({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div className={cn("p-6 pt-0 flex-1", className)} {...props}>
      {children}
    </div>
  );
}

// ==========================================
// 4. FOOTER
// ==========================================
export function CardFooter({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn("flex items-center p-6 pt-0 mt-auto", className)}
      {...props}
    >
      {children}
    </div>
  );
}

// Re-export ProductCard for convenient unified importing from CardBlock
export { ProductCard } from "@/components/custom/blocks/ProductCardBlock";
export type { ProductCardProps, ProductColorOption } from "@/components/custom/blocks/ProductCardBlock";

"use client";

import React, { useState } from "react";
import { cn } from "@/lib/utils";
import {
  Heart,
  ShoppingCart,
  Star,
  Zap,
  CheckCircle2,
  Plus,
  Eye,
} from "lucide-react";

export type ProductCardVariant = "standard" | "compact" | "horizontal";

export interface ProductColorOption {
  name: string;
  value: string; // Tailwind color class or hex string (e.g. 'bg-indigo-600')
}

export interface ProductCardProps {
  className?: string;
  variant?: ProductCardVariant;
  title: string;
  subtitle?: string;
  description?: string;
  price: string;
  originalPrice?: string;
  rating?: number;
  reviewsCount?: number;
  badge?: string;
  badgeVariant?: "emerald" | "rose" | "indigo" | "amber" | "zinc";
  inStock?: boolean;
  image?: React.ReactNode;
  colors?: ProductColorOption[];
  defaultColorIndex?: number;
  onColorChange?: (color: ProductColorOption, index: number) => void;
  onAddToCart?: () => void;
  onBuyNow?: () => void;
  onQuickView?: () => void;
  onFavoriteToggle?: (isLiked: boolean) => void;
  interactive?: boolean;
}

const badgeColorStyles: Record<string, string> = {
  emerald: "bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border-emerald-500/20",
  rose: "bg-rose-500/15 text-rose-600 dark:text-rose-400 border-rose-500/20",
  indigo: "bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 border-indigo-500/20",
  amber: "bg-amber-500/15 text-amber-600 dark:text-amber-400 border-amber-500/20",
  zinc: "bg-zinc-500/15 text-zinc-700 dark:text-zinc-300 border-zinc-500/20",
};

export function ProductCard({
  className,
  variant = "standard",
  title,
  subtitle,
  description,
  price,
  originalPrice,
  rating,
  reviewsCount,
  badge,
  badgeVariant = "emerald",
  inStock = true,
  image,
  colors,
  defaultColorIndex = 0,
  onColorChange,
  onAddToCart,
  onBuyNow,
  onQuickView,
  onFavoriteToggle,
  interactive = false,
}: ProductCardProps) {
  const [liked, setLiked] = useState(false);
  const [selectedColorIdx, setSelectedColorIdx] = useState(defaultColorIndex);

  const handleFavoriteClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    const newLiked = !liked;
    setLiked(newLiked);
    onFavoriteToggle?.(newLiked);
  };

  const handleColorSelect = (color: ProductColorOption, idx: number, e: React.MouseEvent) => {
    e.stopPropagation();
    setSelectedColorIdx(idx);
    onColorChange?.(color, idx);
  };

  if (variant === "horizontal") {
    return (
      <article
        className={cn(
          "w-full rounded-2xl bg-primary/[0.008] border border-primary/20 p-4 flex flex-col sm:flex-row items-center gap-4 text-foreground transition-all duration-200",
          interactive && "hover:shadow-md hover:border-primary/50 hover:-translate-y-0.5",
          className
        )}
      >
        {/* Thumbnail Image */}
        <div className="size-24 rounded-2xl bg-primary/10 border border-primary/20 shrink-0 flex items-center justify-center overflow-hidden">
          {image || <span className="text-3xl font-bold">🛍️</span>}
        </div>

        {/* Content */}
        <div className="flex-1 space-y-1 text-center sm:text-left min-w-0">
          <div className="flex items-center justify-center sm:justify-start gap-2 flex-wrap">
            {badge && (
              <span
                className={cn(
                  "px-2 py-0.5 rounded-md text-[10px] font-extrabold uppercase border",
                  badgeColorStyles[badgeVariant] || badgeColorStyles.emerald
                )}
              >
                {badge}
              </span>
            )}
            {rating !== undefined && (
              <span className="text-xs font-semibold text-amber-500 flex items-center gap-1">
                <Star className="size-3 fill-amber-500" /> {rating}
              </span>
            )}
          </div>
          <h4 className="text-base font-extrabold text-foreground line-clamp-1">{title}</h4>
          {description && (
            <p className="text-xs text-muted-foreground line-clamp-1">{description}</p>
          )}
        </div>

        {/* Price & Action */}
        <div className="flex items-center gap-4 shrink-0 border-t sm:border-t-0 sm:border-l border-border/60 pt-3 sm:pt-0 sm:pl-4 w-full sm:w-auto justify-between sm:justify-end">
          <div className="text-left sm:text-right">
            <span className="text-lg font-bold text-foreground">{price}</span>
            {originalPrice && (
              <p className="text-xs text-muted-foreground line-through">{originalPrice}</p>
            )}
          </div>
          {onAddToCart && (
            <button
              type="button"
              onClick={onAddToCart}
              className="size-10 rounded-xl bg-primary text-primary-foreground flex items-center justify-center hover:opacity-90 transition-opacity active:scale-95 shadow-xs"
            >
              <Plus className="size-5" />
            </button>
          )}
        </div>
      </article>
    );
  }

  return (
    <article
      className={cn(
        "w-full rounded-2xl bg-primary/[0.008] border border-primary/20 overflow-hidden flex flex-col justify-between text-foreground transition-all duration-200 group",
        interactive && "hover:shadow-lg hover:border-primary/50 hover:-translate-y-1",
        className
      )}
    >
      {/* Image Preview Area */}
      <div className="relative aspect-4/3 w-full bg-gradient-to-br from-primary/10 via-primary/5 to-transparent flex items-center justify-center p-0 overflow-hidden">
        {badge && (
          <span
            className={cn(
              "absolute top-3 left-3 px-2.5 py-1 rounded-full text-[10px] font-extrabold uppercase tracking-wider border z-20",
              badgeColorStyles[badgeVariant] || badgeColorStyles.emerald
            )}
          >
            {badge}
          </span>
        )}

        {inStock !== undefined && (
          <div className="absolute top-3 right-3 flex items-center gap-1 px-2 py-0.5 rounded-md bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 text-[10px] font-extrabold z-20">
            <CheckCircle2 className="size-3" /> {inStock ? "In Stock" : "Out of Stock"}
          </div>
        )}

        {onFavoriteToggle && (
          <button
            type="button"
            onClick={handleFavoriteClick}
            className={cn(
              "absolute right-3 p-2 rounded-full bg-background/80 backdrop-blur-xs border border-border text-muted-foreground hover:text-rose-500 transition-colors shadow-2xs z-20",
              inStock !== undefined ? "top-10" : "top-3"
            )}
          >
            <Heart className={cn("size-4", liked && "fill-rose-500 text-rose-500")} />
          </button>
        )}

        {/* Product Visual */}
        <div className="w-full h-full flex items-center justify-center group-hover:scale-105 transition-transform duration-300">
          {image || <span className="text-4xl font-bold">📦</span>}
        </div>
      </div>

      {/* Body Content */}
      <div className="p-4 pb-2 flex-1 flex flex-col justify-between">
        <div className="space-y-1">
          <div className="flex items-center justify-between text-xs text-muted-foreground mb-1">
            {subtitle && <span className="font-semibold text-primary">{subtitle}</span>}
            {rating !== undefined && (
              <span className="flex items-center gap-1 font-semibold text-amber-500 ml-auto">
                <Star className="size-3.5 fill-amber-500" /> {rating}
                {reviewsCount !== undefined && (
                  <span className="text-muted-foreground font-normal">({reviewsCount})</span>
                )}
              </span>
            )}
          </div>

          <h3 className="text-base font-extrabold text-foreground line-clamp-1">{title}</h3>
          {description && (
            <p className="text-xs text-muted-foreground line-clamp-2">{description}</p>
          )}
        </div>

        {/* Color Options Swatches */}
        {colors && colors.length > 0 && (
          <div className="flex items-center justify-between pt-3 mt-2 border-t border-border/40">
            <span className="text-[11px] font-semibold text-muted-foreground">Color</span>
            <div className="flex items-center gap-1.5">
              {colors.map((col, idx) => (
                <button
                  key={col.name || idx}
                  type="button"
                  title={col.name}
                  onClick={(e) => handleColorSelect(col, idx, e)}
                  className={cn(
                    "size-3.5 rounded-full border transition-all",
                    col.value,
                    selectedColorIdx === idx
                      ? "ring-2 ring-primary/30 ring-offset-1 scale-110"
                      : "opacity-75 hover:opacity-100"
                  )}
                />
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Footer / Actions */}
      <div className="p-4 pt-2 flex items-center justify-between border-t border-border/40 mt-1">
        <div>
          <span className="text-lg font-bold text-foreground">{price}</span>
          {originalPrice && (
            <span className="text-xs text-muted-foreground line-through ml-2">
              {originalPrice}
            </span>
          )}
        </div>

        <div className="flex items-center gap-2">
          {onQuickView && (
            <button
              type="button"
              onClick={onQuickView}
              className="px-3 py-2 rounded-xl border border-primary/30 bg-background hover:bg-primary/10 hover:text-primary hover:border-primary/50 text-foreground text-xs font-semibold flex items-center gap-1.5 transition-colors active:scale-95 cursor-pointer"
            >
              <Eye className="size-3.5" /> Quick View
            </button>
          )}

          {onAddToCart && (
            <button
              type="button"
              onClick={onAddToCart}
              className="px-3.5 py-2 rounded-xl bg-primary text-primary-foreground text-xs font-semibold flex items-center gap-1.5 hover:opacity-90 transition-opacity active:scale-95 shadow-xs"
            >
              <ShoppingCart className="size-3.5" /> Add
            </button>
          )}

          {onBuyNow && (
            <button
              type="button"
              onClick={onBuyNow}
              className="px-3.5 py-2 rounded-xl bg-primary text-primary-foreground text-xs font-semibold flex items-center gap-1.5 hover:opacity-90 transition-opacity active:scale-95 shadow-xs"
            >
              <Zap className="size-3.5" /> Buy Now
            </button>
          )}
        </div>
      </div>
    </article>
  );
}

import { Slot } from "@radix-ui/react-slot";
import * as React from "react";

import { cn } from "@/lib/utils";
import { badgeVariants } from "./badge-variants";

type BadgeVariant = "default" | "secondary" | "destructive" | "outline";

type BadgeProps = React.HTMLAttributes<HTMLElement> & {
  className?: string;
  variant?: BadgeVariant;
  asChild?: boolean;
};

function Badge({
  className,
  variant = "default",
  asChild = false,
  ...props
}: BadgeProps) {
  const Comp = asChild ? Slot : "span";

  return (
    <Comp
      data-slot="badge"
      className={cn(badgeVariants({ variant }), className)}
      {...props}
    />
  );
}

export { Badge };

import { cva } from "class-variance-authority";

export const badgeVariants = cva(
  "inline-flex items-center justify-center rounded-md border px-2 py-0.5 text-xs font-medium w-fit whitespace-nowrap shrink-0 [&>svg]:size-3 gap-1 [&>svg]:pointer-events-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive transition-[color,box-shadow] overflow-hidden",
  {
    variants: {
      variant: {
        default:
          "border-transparent bg-primary text-primary-foreground [a&]:hover:bg-primary/90",
        secondary:
          "border-transparent bg-secondary text-secondary-foreground [a&]:hover:bg-secondary/90",
        destructive:
          "border-transparent bg-destructive text-white [a&]:hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        outline:
          "text-foreground [a&]:hover:bg-accent [a&]:hover:text-accent-foreground",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

"use client";

import { cn } from "@/lib/utils";
import {
  ArrowDown,
  ArrowUp,
  Check,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  ChevronsUpDown,
  ChevronUp,
  Download,
  Minus,
  RotateCcw,
  Search,
  X,
} from "lucide-react";
import React, {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";
import { accentStyle } from "@/lib/accent";
import { type Accessor, DataTableContext, type DataTableContextValue, type SortType, TableContext, type TableSize, type TableVariant, getAccentColor, getThemeStyles, resolveAccessor, useDataTable, useTableStyles } from "./table-core";
import { ToggleGroup, ToggleGroupItem } from "./ToggleGroupBlock";

// ==========================================
// DYNAMIC THEME ENGINE
// ==========================================
export type TableColor = "indigo" | "rose" | "emerald" | "zinc" | (string & {});
export type TableAlign = "left" | "center" | "right";

// ==========================================
// LOOK-UP TABLES
// ==========================================
const sizeClasses: Record<TableSize, { th: string; td: string; bar: string }> = {
  sm: {
    th: "px-3 py-2 text-[11px]",
    td: "px-3 py-2 text-xs",
    bar: "px-3 py-2.5",
  },
  md: {
    th: "px-4 lg:px-6 py-3.5 text-xs",
    td: "px-4 lg:px-6 py-3.5 text-sm",
    bar: "px-4 lg:px-6 py-4",
  },
  lg: { th: "px-6 py-4 text-xs", td: "px-6 py-4 text-base", bar: "px-6 py-5" },
};

// `soft` rows breathe a little more and indent the outer columns on wide
// screens, so the first and last cells line up with the toolbar above.
const softSizeClasses: Record<TableSize, { th: string; td: string; bar: string }> = {
  sm: {
    th: "px-3 py-2 text-[10px]",
    td: "px-3 py-2.5 text-xs",
    bar: "px-3 py-2.5",
  },
  md: {
    th: "px-4 py-3 text-[11px] lg:first:pl-6 lg:last:pr-6",
    td: "px-4 py-3.5 text-sm lg:first:pl-6 lg:last:pr-6",
    bar: "px-4 py-3.5 lg:px-6",
  },
  lg: {
    th: "px-6 py-3.5 text-[11px]",
    td: "px-6 py-4 text-base",
    bar: "px-6 py-4",
  },
};

const sizesFor = (variant: TableVariant) =>
  variant === "soft" ? softSizeClasses : sizeClasses;

/**
 * The `soft` variant's tints, mixed from the table colour on the wrapper so
 * every part reads them: the well (header band, search, filters), the row
 * hover and selected washes, and the tint an applied filter takes.
 */
const softTokens = (color?: string) =>
  ({
    "--tbl-accent": getAccentColor(color),
    "--tbl-well":
      "color-mix(in oklab, var(--tbl-accent) 5%, color-mix(in oklab, var(--foreground) 5%, var(--card)))",
    "--tbl-row-hover": "color-mix(in oklab, var(--tbl-accent) 4%, var(--card))",
    "--tbl-row-selected":
      "color-mix(in oklab, var(--tbl-accent) 8%, var(--card))",
    "--tbl-tint": "color-mix(in oklab, var(--tbl-accent) 10%, var(--card))",
    "--tbl-accent-ink":
      "color-mix(in oklab, var(--tbl-accent) 78%, var(--foreground))",
  }) as React.CSSProperties;

// Outside a `soft` table these fall back to the theme's muted surface, so
// the shared parts (row actions, badges, empty states) work in every variant.
const WELL = "bg-[var(--tbl-well,var(--muted))]";
const FOCUS_RING =
  "outline-none focus-visible:ring-2 focus-visible:ring-[color-mix(in_oklab,var(--tbl-accent,var(--primary))_60%,transparent)]";

interface VariantSkin {
  wrapper: string;
  heading: string;
  footer: string;
  headerRow: string;
  row: string;
  selectedRow: string;
  expanded: string;
}

const variantClasses: Record<TableVariant, VariantSkin> = {
  default: {
    wrapper: "w-full bg-card text-card-foreground border border-primary/20 rounded-xl shadow-sm overflow-hidden",
    heading: "border-b border-primary/15 bg-card",
    footer: "border-t border-primary/15 bg-card",
    headerRow: "bg-primary/[0.04] dark:bg-primary/[0.08] border-b border-primary/15",
    row: "group border-b border-primary/10 last:border-0 transition-colors bg-card hover:bg-primary/[0.05] dark:hover:bg-primary/[0.08]",
    selectedRow: "bg-primary/[0.08] dark:bg-primary/[0.12]",
    expanded: "bg-primary/[0.03] dark:bg-primary/[0.06] border-b border-primary/10",
  },
  minimal: {
    wrapper: "w-full bg-transparent",
    heading: "border-b border-primary/15",
    footer: "border-t border-primary/15",
    headerRow: "border-b-2 border-primary/25",
    row: "group border-b border-primary/10 last:border-0 transition-colors bg-transparent hover:bg-primary/[0.05] dark:hover:bg-primary/[0.08]",
    selectedRow: "bg-primary/[0.08] dark:bg-primary/[0.12]",
    expanded: "bg-primary/[0.03] dark:bg-primary/[0.06] border-b border-primary/10",
  },
  glass: {
    wrapper:
      "w-full bg-card/40 text-card-foreground backdrop-blur-xl border border-primary/20 rounded-xl shadow-xl overflow-hidden",
    heading: "border-b border-primary/15",
    footer: "border-t border-primary/15",
    headerRow:
      "bg-primary/[0.06] border-b border-primary/15",
    row: "group border-b border-primary/10 last:border-0 transition-colors hover:bg-primary/[0.05]",
    selectedRow: "bg-primary/[0.12]",
    expanded:
      "bg-primary/[0.05] border-b border-primary/10",
  },
  // Separate borders: the dividers live on the cells, so a sticky cell paints
  // its own. The wrapper does not clip, so filter and page-size menus can
  // open past its edge; the scroll area rounds itself instead.
  soft: {
    wrapper:
      "relative w-full rounded-[20px] bg-card text-card-foreground ring-1 ring-foreground/[0.08] shadow-[0_1px_2px_rgb(16_24_40/0.04),0_16px_32px_-20px_rgb(16_24_40/0.14)] dark:shadow-none",
    heading: "border-b border-foreground/[0.08]",
    footer: "border-t border-foreground/[0.08]",
    // The band is painted on the row and on its cells, so the hairline gaps
    // fractional column widths leave between cells show the same colour.
    headerRow:
      "bg-[var(--tbl-well)] [&>*]:bg-[var(--tbl-well)] [&>*]:border-b [&>*]:border-foreground/[0.08]",
    // Dividers sit on top of each row (none on the first), so the last row
    // never doubles the footer's line — even when hidden detail rows follow it.
    row: "group transition-colors duration-150 hover:bg-[var(--tbl-row-hover)] [&>*]:border-t [&>*]:border-foreground/[0.08] [&:first-child>*]:border-t-0",
    selectedRow: "bg-[var(--tbl-row-selected)] hover:bg-[var(--tbl-row-selected)]",
    // An open detail row reads as part of the row above it: no divider between.
    expanded: "bg-[color-mix(in_oklab,var(--tbl-well)_60%,var(--card))]",
  },
};

