                  sortDirection
                    ? "text-[var(--tbl-accent-ink)]"
                    : "opacity-40 group-hover/sort:opacity-100",
                )}
              />
            </button>
          ) : (
            children
          )}
        </th>
      );
    }

    return (
      <th
        ref={ref}
        scope="col"
        aria-sort={
          sortable
            ? sortDirection === "asc"
              ? "ascending"
              : sortDirection === "desc"
                ? "descending"
                : "none"
            : undefined
        }
        className={cn(
          sizeClasses[size].th,
          "whitespace-nowrap font-semibold uppercase tracking-wider text-muted-foreground select-none",
          alignClasses[align],
          sticky && stickyHead[variant],
          className,
