const hexToRgb = (hex: string) => {
  let cleanHex = hex.replace(/^#/, "");
  if (cleanHex.length === 3)
    cleanHex = cleanHex
      .split("")
      .map((x) => x + x)
      .join("");
  const result = /^([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(cleanHex);
  return result
    ? `${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}`
    : "99, 102, 241";
};

export const getThemeStyles = (color?: string) => {
  if (!color || color === "default" || color === "primary") {
    return { theme: colorThemes.primary, style: {} };
  }
  const resolved = resolveAccent(color);
  const target = resolved || color;
  if (target && target.startsWith("#")) {
    const rgb = hexToRgb(target);
    return {
      theme: {
        bg: "bg-[var(--theme-color)] text-white",
        text: "text-[var(--theme-color)]",
        bgSoft: "bg-[rgba(var(--theme-color-rgb),0.1)]",
        border: "border-[var(--theme-color)]",
        borderSoft: "border-[rgba(var(--theme-color-rgb),0.18)]",
        focusRing: "focus:border-[var(--theme-color)] focus:outline-none",
        hoverBorder: "hover:border-[var(--theme-color)]",
        hoverBgSoft: "hover:bg-[rgba(var(--theme-color-rgb),0.08)]",
      },
      style: {
        "--theme-color": target,
        "--theme-color-rgb": rgb,
      } as React.CSSProperties,
    };
  }
  return { theme: colorThemes[color] || colorThemes.primary, style: {} };
};

const accentHex: Record<string, string> = {
  lavender: "#9b8afb",
  indigo: "#6366f1",
  rose: "#f43f5e",
  emerald: "#10b981",
  zinc: "#3f3f46",
};

/** The table colour as a CSS colour, for the tints the `soft` variant mixes from it. */
export const getAccentColor = (color?: string) => {
  if (!color || color === "default" || color === "primary") return "var(--primary)";
  const resolved = resolveAccent(color);
  if (resolved) return resolved;
  if (color.startsWith("#") || color.startsWith("var(")) return color;
  return accentHex[color] ?? "var(--primary)";
};

export interface TableStyleContext {
  variant: TableVariant;
  size: TableSize;
  theme: Record<string, string>;
}

export const TableContext = createContext<TableStyleContext>({
  variant: "default",
  size: "md",
  theme: colorThemes.primary,
});

export const useTableStyles = () => useContext(TableContext);

export type Accessor<T> = string | ((row: T) => unknown);

export type SortType = "auto" | "string" | "number" | "date";

export function resolveAccessor<T>(row: T, accessor: Accessor<T>): unknown {
  if (typeof accessor === "function") return accessor(row);
  return accessor
    .split(".")
    .reduce<unknown>(
      (acc, key) =>
        acc == null ? acc : (acc as Record<string, unknown>)[key],
      row,
    );
}

export interface DataTableContextValue<T = unknown> {
  /** Exactly what you passed in. */
  sourceRows: T[];
  /** After search + sort, before paging. */
  filteredRows: T[];
  /** The current page — what you render. */
  rows: T[];
  getRowId: (row: T) => string | number;

  search: string;
  setSearch: (value: string) => void;

  /** Active filters by id, as set by DataTableFilter and DataTableTabs. */
  filters: Record<string, string>;
  /** `null` clears the filter. Rows match when the accessor's value equals `value`. */
  setFilter: (id: string, accessor: Accessor<T>, value: string | null) => void;
  /**
   * How many rows a filter value would leave: search and every other filter
   * apply, this one is swapped for `value` (`null` for "any").
   */
  countFor: (id: string, accessor: Accessor<T>, value: string | null) => number;
  /** Search or any filter is narrowing the rows. */
  isFiltered: boolean;
  /** Clears search, every filter and the sort. */
  resetAll: () => void;

  sort: { id: string; direction: "asc" | "desc" } | null;
  toggleSort: (id: string, accessor: Accessor<T>, type: SortType) => void;

  page: number;
  setPage: (page: number) => void;
  pageSize: number;
  setPageSize: (size: number) => void;
  pageSizeOptions: number[];
  totalPages: number;
  total: number;
  from: number;
  to: number;

  selectedIds: Set<string | number>;
  selectedRows: T[];
  isSelected: (id: string | number) => boolean;
  toggleRow: (id: string | number) => void;
  toggleAllOnPage: () => void;
  clearSelection: () => void;
  isAllPageSelected: boolean;
  isSomePageSelected: boolean;

  isExpanded: (id: string | number) => boolean;
  toggleExpanded: (id: string | number) => void;

  theme: Record<string, string>;
  themeStyle?: React.CSSProperties;
}

export const DataTableContext = createContext<DataTableContextValue | null>(null);

export function useDataTable<T = unknown>(): DataTableContextValue<T> {
  const ctx = useContext(DataTableContext);
  if (!ctx) {
    throw new Error("useDataTable must be used inside <DataTable>.");
  }
  return ctx as DataTableContextValue<T>;
}

import type { CSSProperties } from "react";

/**
 * Bridging the docs colour picker into a preview.
 *
 * Most blocks are already written against the `--primary` token (`bg-primary`,
 * `ring-primary/30`, `text-primary-foreground`…). Rather than teaching each one a
 * bespoke `color` prop, a demo can repoint that token for its own subtree and
 * every one of those classes follows along.
 */

/** The swatches the picker offers, as concrete CSS colours. */
const PRESET_HEX: Record<string, string> = {
  lavender: "#9b8afb",
  indigo: "#6366f1",
  rose: "#f43f5e",
  emerald: "#10b981",
};

/** True when the picker sits on "Default" — the page theme should win. */
export function isDefaultAccent(color?: string): boolean {
  return !color || color === "primary" || color === "default";
}

/**
 * Turns a picker value into a CSS colour, or null for "Default" — meaning
 * nothing should be overridden, so the theme (and the sidebar customizer)
 * keeps control.
 */
export function resolveAccent(color?: string): string | null {
  if (isDefaultAccent(color)) return null;
  return PRESET_HEX[color as string] ?? (color as string);
}

/**
 * The picker value in a form every block accepts. Blocks know the older swatch
 * names but not "lavender" — and since that is also a CSS named colour
 * (#e6e6fa), a block that passes unknown names straight through would paint
 * the wrong shade, while others fall back to a different palette. Demos that
 * hand the picker value to such a block run it through this first. Every
 * other value is returned untouched.
 */
export function toBlockColor(color: string): string;
export function toBlockColor(color: string | undefined): string | undefined;
export function toBlockColor(color?: string): string | undefined {
  return color === "lavender" ? PRESET_HEX.lavender : color;
}

function parseHex(input: string): [number, number, number] | null {
  const hex = input.trim().replace(/^#/, "");
  if (/^[a-f\d]{3}$/i.test(hex)) {
    const [r, g, b] = hex.split("");
    return [parseInt(r + r, 16), parseInt(g + g, 16), parseInt(b + b, 16)];
  }
  if (/^[a-f\d]{6}$/i.test(hex)) {
    return [
      parseInt(hex.slice(0, 2), 16),
      parseInt(hex.slice(2, 4), 16),
      parseInt(hex.slice(4, 6), 16),
    ];
  }
  return null;
}

/** Legible foreground for content sitting on a filled `color` swatch. */
export function accentForeground(color: string): string {
  const rgb = parseHex(color);
  if (!rgb) return "#ffffff";
  const channel = (v: number) => {
    const c = v / 255;
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  };
  const luminance =
    0.2126 * channel(rgb[0]) +
    0.7152 * channel(rgb[1]) +
    0.0722 * channel(rgb[2]);
  return luminance > 0.45 ? "#09090b" : "#ffffff";
}

/** The theme tokens a picked accent repoints, as `--name` → value. */
export function accentTokens(color?: string): Record<string, string> {
  const resolved = resolveAccent(color);
  if (!resolved) return {};
  return {
    "--primary": resolved,
    "--primary-foreground": accentForeground(resolved),
    "--ring": resolved,
  };
}

/**
 * Inline style repointing `--primary` at the picked accent for one subtree.
 * `--primary-foreground` is derived alongside it, otherwise a light pick leaves
 * `text-primary-foreground` content unreadable on its own fill. Returns `{}` on
 * "Default" so the page theme still wins.
 */
export function accentStyle(color?: string): CSSProperties {
  return accentTokens(color) as CSSProperties;
}

"use client";

import { cn } from "@/lib/utils";
import React, {
  createContext,
  forwardRef,
  useContext,
  useEffect,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { getThemeStyles } from "./toggle-group-theme";

// ==========================================
// THEME & CONFIGURATION
// ==========================================
export type ToggleGroupColor =
  | "primary"
  | "indigo"
  | "rose"
  | "emerald"
  | "zinc"
  | (string & {});
/**
 * `segmented` is a pill track whose highlight slides to the pressed item —
 * a view switch (Day / Week / Month). In a single group the pressed item
 * stays pressed when clicked again, and the arrow keys move the choice.
 */
export type ToggleGroupVariant = "default" | "outline" | "ghost" | "segmented";
export type ToggleGroupSize = "sm" | "md" | "lg";
export type ToggleGroupType = "single" | "multiple";

// ==========================================
// CONTEXT
// ==========================================
interface ToggleGroupContextProps {
  type: ToggleGroupType;
  value: string | string[];
  onValueChange: (value: string | string[]) => void;
  variant: ToggleGroupVariant;
  color: ToggleGroupColor;
  size: ToggleGroupSize;
  disabled: boolean;
  theme: Record<string, string>;
  /** Segmented only: the sliding highlight has been placed, so items drop their own. */
  pillReady: boolean;
}

// The segmented track. Inside a `soft` table it takes the table's own well
// (`--tbl-well`), so the tabs and the search field share one tint.
const SEGMENTED_TRACK =
  "bg-[var(--tbl-well,color-mix(in_oklab,var(--primary)_5%,color-mix(in_oklab,var(--foreground)_5%,var(--card))))]";
const SEGMENTED_PILL = "bg-card shadow-sm ring-1 ring-foreground/[0.08]";

const segmentedHeights: Record<ToggleGroupSize, string> = {
  sm: "h-9",
  md: "h-10",
  lg: "h-12",
};

// Layout effects warn during server rendering on older React; the pill is
// only ever measured in the browser anyway.
const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? useLayoutEffect : useEffect;

const ToggleGroupContext = createContext<ToggleGroupContextProps | null>(null);

function useToggleGroup() {
  const context = useContext(ToggleGroupContext);
  if (!context) {
    throw new Error("ToggleGroupItem must be used within a ToggleGroup");
  }
  return context;
}

// ==========================================
// GROUP COMPONENT
// ==========================================
/** Everything both selection modes share. */
interface ToggleGroupBaseProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "defaultValue"> {
  variant?: ToggleGroupVariant;
  color?: ToggleGroupColor;
  size?: ToggleGroupSize;
  disabled?: boolean;
}

/** The default: one item pressed at a time, so the value is a string. */
export interface ToggleGroupSingleProps extends ToggleGroupBaseProps {
  type?: "single";
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

/** `type="multiple"` — value and callback both deal in arrays. */
export interface ToggleGroupMultipleProps extends ToggleGroupBaseProps {
  type: "multiple";
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
}

/**
 * Discriminated on `type`, so a single group hands your callback a `string`
 * and a multiple group hands it a `string[]`, with no cast either way.
 */
export type ToggleGroupProps = ToggleGroupSingleProps | ToggleGroupMultipleProps;

/** The two modes collapsed, which is what the implementation works with. */
type ToggleGroupImplProps = ToggleGroupBaseProps & {
  type?: ToggleGroupType;
  value?: string | string[];
  defaultValue?: string | string[];
  onValueChange?: (value: string | string[]) => void;
};

const ToggleGroupImpl = forwardRef<HTMLDivElement, ToggleGroupImplProps>(
  (
    {
      type = "single",
      value: controlledValue,
      defaultValue,
      onValueChange,
      variant = "default",
      color = "primary",
      size = "md",
      disabled = false,
      className,
      children,
      onKeyDown,
      style: styleProp,
      ...props
    },
    ref,
  ) => {
    const { theme, style } = getThemeStyles(color as string);
    const [uncontrolledValue, setUncontrolledValue] = React.useState<
      string | string[]
    >(defaultValue !== undefined ? defaultValue : type === "single" ? "" : []);

    const isControlled = controlledValue !== undefined;
    const currentValue = isControlled ? controlledValue : uncontrolledValue;

    const handleValueChange = (newValue: string | string[]) => {
      if (!isControlled) setUncontrolledValue(newValue);
      if (onValueChange) onValueChange(newValue);
    };

    const groupRef = useRef<HTMLDivElement>(null);
    useImperativeHandle(ref, () => groupRef.current as HTMLDivElement);

    // One highlight that slides between items, for a single segmented group.
    // It is measured from the pressed item, so labels of any width work.
    const sliding = variant === "segmented" && type === "single";
    const pillRef = useRef<HTMLSpanElement>(null);
    const placedRef = useRef(false);
    const [pillReady, setPillReady] = useState(false);
    const valueKey = Array.isArray(currentValue)
      ? currentValue.join("|")
      : currentValue;

    useIsomorphicLayoutEffect(() => {
      const group = groupRef.current;
      const pill = pillRef.current;
      if (!sliding || !group || !pill) return;

      const place = () => {
        const active = group.querySelector<HTMLElement>(
          '[data-toggle-item][data-state="on"]',
        );
        if (!active) {
          pill.style.opacity = "0";
          return;
        }
        const g = group.getBoundingClientRect();
        const a = active.getBoundingClientRect();
        // The first placement jumps; every later one slides.
        if (!placedRef.current) pill.style.transition = "none";
        pill.style.width = `${a.width}px`;
        pill.style.height = `${a.height}px`;
        pill.style.transform = `translate(${a.left - g.left - group.clientLeft + group.scrollLeft}px, ${a.top - g.top - group.clientTop}px)`;
        pill.style.opacity = "1";
        if (!placedRef.current) {
          void pill.offsetWidth;
          pill.style.transition = "";
          placedRef.current = true;
          setPillReady(true);
        }
      };

      place();
      const observer = new ResizeObserver(place);
      observer.observe(group);
      group
        .querySelectorAll<HTMLElement>("[data-toggle-item]")
        .forEach((item) => observer.observe(item));
      return () => observer.disconnect();
    }, [sliding, valueKey]);

    // Segmented single groups behave as a radio group: the arrow keys move
    // the choice (and focus) to the next enabled item.
    const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
      onKeyDown?.(event);
      if (event.defaultPrevented || !sliding || disabled) return;
      const keys = ["ArrowRight", "ArrowDown", "ArrowLeft", "ArrowUp", "Home", "End"];
      if (!keys.includes(event.key)) return;
      const items = Array.from(
        groupRef.current?.querySelectorAll<HTMLButtonElement>(
          "[data-toggle-item]:not(:disabled)",
        ) ?? [],
      );
      if (!items.length) return;
      const from = items.findIndex((item) => item === document.activeElement);
      const last = items.length - 1;
      const forward = event.key === "ArrowRight" || event.key === "ArrowDown";
      const next =
        event.key === "Home"
          ? 0
          : event.key === "End"
            ? last
            : forward
              ? from >= last ? 0 : from + 1
              : from <= 0 ? last : from - 1;
      const target = items[next];
      if (!target) return;
      event.preventDefault();
      target.focus();
      const nextValue = target.dataset.value;
      if (nextValue !== undefined) handleValueChange(nextValue);
    };

    return (
      <ToggleGroupContext.Provider
        value={{
          type,
          value: currentValue,
          onValueChange: handleValueChange,
          variant,
          color,
          size,
          disabled,
          theme,
          pillReady: sliding && pillReady,
        }}
      >
        <div
          ref={groupRef}
          role={sliding ? "radiogroup" : "group"}
          className={cn(
            "inline-flex flex-wrap items-center gap-1",
            variant === "default" &&
              "p-1 rounded-xl bg-muted border border-border/50",
            variant === "segmented" &&
              cn(
                "relative flex-nowrap gap-0 rounded-full p-1",
                SEGMENTED_TRACK,
                segmentedHeights[size],
              ),
            className,
          )}
          style={{ ...style, ...styleProp }}
          onKeyDown={handleKeyDown}
          {...props}
        >
          {sliding && (
            <span
              ref={pillRef}
              aria-hidden="true"
              className={cn(
                "pointer-events-none absolute left-0 top-0 rounded-full opacity-0 transition-[transform,width,height] duration-300 ease-[cubic-bezier(0.22,1,0.36,1)] motion-reduce:transition-none",
                SEGMENTED_PILL,
              )}
            />
          )}
          {children}
        </div>
      </ToggleGroupContext.Provider>
    );
  },
);
ToggleGroupImpl.displayName = "ToggleGroup";

/**
 * The implementation is written against the collapsed props; this cast is
 * what hands callers the discriminated pair instead.
 */
export const ToggleGroup = ToggleGroupImpl as React.ForwardRefExoticComponent<
  ToggleGroupProps & React.RefAttributes<HTMLDivElement>
>;

// ==========================================
// ITEM COMPONENT
// ==========================================
export interface ToggleGroupItemProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  value: string;
}

export const ToggleGroupItem = forwardRef<
  HTMLButtonElement,
  ToggleGroupItemProps
>(({ value, disabled: itemDisabled, className, children, ...props }, ref) => {
  const context = useToggleGroup();
  const {
    type,
    value: groupValue,
    onValueChange,
    variant,
    size,
    disabled: groupDisabled,
    theme,
    pillReady,
  } = context;

  const isDisabled = groupDisabled || itemDisabled;
  const segmented = variant === "segmented";
  const radio = segmented && type === "single";

  // Check if active
  const isActive =
    type === "single"
      ? groupValue === value
      : Array.isArray(groupValue) && groupValue.includes(value);

  const handleToggle = () => {
    if (isDisabled) return;

    if (type === "single") {
      // A segmented choice is a radio: pressing it again keeps it.
      if (radio) {
        if (!isActive) onValueChange(value);
        return;
      }
      onValueChange(isActive ? "" : value);
    } else {
      const currentArray = Array.isArray(groupValue) ? groupValue : [];
      if (isActive) {
        onValueChange(currentArray.filter((v) => v !== value));
      } else {
        onValueChange([...currentArray, value]);
      }
    }
  };

  const sizeStyles = {
    sm: "h-8 px-2.5 text-xs",
    md: "h-10 px-3.5 text-sm",
    lg: "h-12 px-5 text-base",
  };

  const segmentedSizes = {
    sm: "h-full px-3 text-[13px]",
    md: "h-full px-4 text-sm",
    lg: "h-full px-5 text-base",
  };

  const getVariantStyles = () => {
    if (segmented) {
      return cn(
        "relative z-[1] whitespace-nowrap rounded-full text-muted-foreground transition-colors hover:text-foreground focus-visible:ring-primary/60 focus-visible:ring-offset-0",
        segmentedSizes[size],
        isActive && "text-foreground",
        // Until the sliding highlight is measured (and in multiple groups,
        // which have no single highlight) the pressed item paints its own.
        isActive && !pillReady && SEGMENTED_PILL,
      );
    }
    if (isActive) {
      switch (variant) {
        case "outline":
          return cn(theme.border, "shadow-sm");
        case "ghost":
          return cn(theme.text, "bg-muted");
        case "default":
        default:
          return cn(theme.bg, "shadow-md");
      }
    }

    // Inactive states
    switch (variant) {
      case "outline":
        return "border border-border bg-transparent text-muted-foreground hover:bg-muted";
      case "ghost":
        return "bg-transparent text-muted-foreground hover:bg-muted";
      case "default":
      default:
        return "bg-transparent text-muted-foreground hover:bg-muted/50";
    }
  };

  return (
    <button
      ref={ref}
      type="button"
      role={type === "single" ? "radio" : "checkbox"}
      aria-checked={isActive}
      disabled={isDisabled}
      data-toggle-item=""
      data-state={isActive ? "on" : "off"}
      data-value={value}
      // A segmented radio group is one tab stop; the arrow keys move inside it.
      tabIndex={radio ? (isActive || groupValue === "" ? 0 : -1) : undefined}
      onClick={handleToggle}
      className={cn(
        "inline-flex items-center justify-center gap-2 rounded-lg font-medium transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed",
        sizeStyles[size],
        getVariantStyles(),
        className,
      )}
      {...props}
    >
      {children}
    </button>
  );
});
ToggleGroupItem.displayName = "ToggleGroupItem";

"use client";

import React from "react";

const colorThemes: Record<string, Record<string, string>> = {
  // The theme's own accent, so a group follows whatever `--primary` the
  // consumer set — the same contract Button and Input honour.
  primary: {
    bg: "bg-primary text-primary-foreground",
    text: "text-primary",
    border: "border-primary/30 text-primary bg-primary/10",
  },
  indigo: {
    bg: "bg-indigo-500 text-white",
    text: "text-indigo-600 dark:text-indigo-400",
    border:
      "border-indigo-500 text-indigo-600 dark:text-indigo-400 bg-indigo-50 dark:bg-indigo-500/10",
  },
  rose: {
    bg: "bg-rose-500 text-white",
    text: "text-rose-600 dark:text-rose-400",
    border:
      "border-rose-500 text-rose-600 dark:text-rose-400 bg-rose-50 dark:bg-rose-500/10",
  },
  emerald: {
    bg: "bg-emerald-500 text-white",
    text: "text-emerald-600 dark:text-emerald-400",
    border:
      "border-emerald-500 text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-500/10",
  },
  zinc: {
    bg: "bg-zinc-900 text-white dark:bg-zinc-100 dark:text-zinc-900",
    text: "text-zinc-900 dark:text-zinc-100",
    border:
      "border-zinc-900 dark:border-zinc-100 text-zinc-900 dark:text-zinc-100 bg-zinc-100 dark:bg-zinc-800",
  },
};

const hexToRgb = (hex: string) => {
  let cleanHex = hex.replace(/^#/, "");
  if (cleanHex.length === 3)
    cleanHex = cleanHex
      .split("")
      .map((x) => x + x)
      .join("");
  const result = /^([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(cleanHex);
  return result
    ? `${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}`
    : "99, 102, 241";
};

export const getThemeStyles = (color: string) => {
  if (color && color.startsWith("#")) {
    const rgb = hexToRgb(color);
    return {
      theme: {
        bg: "bg-[var(--toggle-color)] text-white",
        text: "text-[var(--toggle-color)]",
        border:
          "border-[var(--toggle-color)] text-[var(--toggle-color)] bg-[rgba(var(--toggle-rgb),0.1)]",
      },
      style: {
        "--toggle-color": color,
        "--toggle-rgb": rgb,
      } as React.CSSProperties,
    };
  }
  return { theme: colorThemes[color] || colorThemes.primary, style: {} };
};

import { useEffect, useState } from "react";
import { isDefaultAccent, resolveAccent } from "@/lib/accent";

/**
 * Bridges the design tokens in CSS into the plain strings third-party chart
 * libraries expect.
 *
 * Recharts, Chart.js, AG Grid and friends take colours as values, not as
 * classes, so `text-muted-foreground` means nothing to them. Reading the
 * custom properties off `<html>` and `<body>` keeps one source of truth: change a
 * token in globals.css, switch theme presets, or pick an active accent color,
 * and every chart follows.
 */
export type ChartTokens = {
  foreground: string;
  muted: string;
  border: string;
  card: string;
  primary: string;
  /** Categorical palette, in the order series should be assigned. */
  series: string[];
};

/**
 * Fallback series colours when CSS tokens are not available.
 */
const DEFAULT_SERIES = ["#6366f1", "#06b6d4", "#f59e0b", "#ec4899", "#10b981", "#8b5cf6"];

const FALLBACK: ChartTokens = {
  foreground: "#18181b",
  muted: "#71717a",
  border: "#e4e4e7",
  card: "#ffffff",
  primary: "#6366f1",
  series: DEFAULT_SERIES,
};

let colorCanvas: HTMLCanvasElement | null = null;

/**
 * Normalizes any CSS color (such as oklch(...), hsl(...), etc.) into a
 * canonical color format supported by Canvas and SVG renderers.
 */
function normalizeColor(color: string): string {
  if (typeof window === "undefined" || !color) return color;
  const trimmed = color.trim();
  if (trimmed.startsWith("#") || trimmed.startsWith("rgb")) return trimmed;
  try {
    if (!colorCanvas) colorCanvas = document.createElement("canvas");
    colorCanvas.width = 1;
    colorCanvas.height = 1;
    const ctx = colorCanvas.getContext("2d");
    if (!ctx) return trimmed;
    ctx.fillStyle = trimmed;
    return ctx.fillStyle || trimmed;
  } catch {
    return trimmed;
  }
}

function readTokens(color?: string): ChartTokens {
  if (typeof window === "undefined") return FALLBACK;

  const bodyStyles = typeof document !== "undefined" && document.body ? getComputedStyle(document.body) : null;
  const rootStyles = getComputedStyle(document.documentElement);

  const read = (name: string, fallback: string) => {
    const val = bodyStyles?.getPropertyValue(name).trim() || rootStyles.getPropertyValue(name).trim();
    return val || fallback;
  };

  const explicitAccent = !isDefaultAccent(color) ? resolveAccent(color) : null;
  const resolvedPrimary = normalizeColor(explicitAccent || read("--primary", FALLBACK.primary));

  const chart1 = resolvedPrimary;
  const chart2 = normalizeColor(read("--chart-2", DEFAULT_SERIES[1]));
  const chart3 = normalizeColor(read("--chart-3", DEFAULT_SERIES[2]));
  const chart4 = normalizeColor(read("--chart-4", DEFAULT_SERIES[3]));
  const chart5 = normalizeColor(read("--chart-5", DEFAULT_SERIES[4]));
  const chart6 = normalizeColor(read("--chart-1", DEFAULT_SERIES[5]));

  return {
    foreground: read("--foreground", FALLBACK.foreground),
    muted: read("--muted-foreground", FALLBACK.muted),
    border: read("--border", FALLBACK.border),
    card: read("--card", FALLBACK.card),
    primary: resolvedPrimary,
    series: [chart1, chart2, chart3, chart4, chart5, chart6],
  };
}

/**
 * Re-reads on theme or accent change. Watches both `<html>` (where theme customizer
 * and next-themes apply classes and custom properties) and `<body>` (where active accent
 * overrides are attached).
 */
export function useChartTokens(color?: string): ChartTokens {
  const [tokens, setTokens] = useState<ChartTokens>(() => readTokens(color));

  useEffect(() => {
    const sync = () => setTokens(readTokens(color));
    sync();

    const observer = new MutationObserver(sync);
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class", "style", "data-theme"],
    });

    if (typeof document !== "undefined" && document.body) {
      observer.observe(document.body, {
        attributes: true,
        attributeFilter: ["class", "style"],
      });
    }

    return () => observer.disconnect();
  }, [color]);

  return tokens;
}
